/**
 * 訂單變動的事件通道（桌邊點單計劃 [S11]〜[S16]）。
 *
 * 用 SSE（伺服器送事件）：單向、`node:http` 原生就能寫、斷線客戶端自己重連。
 * ★不用 WebSocket★——POS 不需要往回推東西，而 Node 原生沒有 WebSocket 伺服器，
 * 要拉套件，跟這個專案的零依賴家規衝突。
 * ★不用 SignalR★——那是 .NET 生態的，接它得另起一個服務當中繼。
 */

import type { ServerResponse } from "node:http";

/**
 * 一則事件。★只帶「哪張單、哪一桌、什麼變了」，不帶整張單的內容★（計劃 [S12]）。
 *
 * 為什麼不塞整張單：推的當下那張單可能又被改了，收到的人拿到的是過期快照
 * 卻以為是最新的。**事件是「去重讀」的信號，不是資料來源。**
 */
export interface OrderEvent {
  /** 什麼變了：客人在手機上送了一輪單／店員動了什麼／單子沒了 */
  kind: "guest-sent" | "order-changed" | "order-gone";
  orderId: string;
  table: string | null;
  at: string;
}

/** 心跳間隔。中間的代理常在 30〜60 秒沒資料就切線,15 秒有餘裕。 */
export const HEARTBEAT_MS = 15_000;

const clients = new Set<ServerResponse>();
let heartbeat: NodeJS.Timeout | null = null;

/** 目前有幾個連線（測試與健檢用）。 */
export function clientCount(): number {
  return clients.size;
}

function startHeartbeat(): void {
  if (heartbeat) return;
  // ★心跳讓中間的代理不會把閒置連線切掉★（計劃 [S14]）。
  // SSE 的註解行（冒號開頭）不會被當成事件,客戶端會忽略。

/**
 * 桌邊點單的客人入口（桌邊結帳計劃 [S1]〜[S3]）。
 *
 * ★這個檔存在的唯一理由是「能力要小」★：客人端只有這幾件事——看菜單、看有哪些桌、
 * 算一台購物車多少錢、把整台購物車送進那一桌的單（送廚房）、外帶報價、外帶結帳。
 *
 * ★內用的結帳只能在 POS★（桌邊送單計劃,2026-09-10 改成吃完再結）：這裡沒有內用結帳。
 * ★外帶可以在手機上結帳★（桌邊外帶結帳計劃,Enzo 2026-09-11 裁）：外帶結帳只會開一張新的單,
 * 送廚房與結帳包在 order.ts 的 checkoutTakeout 裡,這個檔只呼叫它。
 * ★客人改不動任何已經在單上的東西★：送出、打折、換桌、取消、改數量、讀單，
 * 在這裡★根本沒有對應的函式★，不是被判斷擋下來的。送單只會「整批加進去」。
 *
 * 為什麼是「不存在」不是「擋下來」：擋下來意味著那條路寫在同一支處理程式裡，
 * 只差一個判斷；判斷寫錯就全開了。
 */

import { MENU } from "./menu";
import { TABLES, findTable } from "./tables";
import { DomainError, Order, checkoutTakeout, priceCart, sendToTable } from "./order";
import { publish } from "./events";

/**
 * 把網址上的桌號驗成真的桌（計劃 [S3]）。
 * ★不存在的桌號要退件★——放行的話會生出一張掛在不存在座位上的單。
 */
export function requireGuestTable(raw: unknown): string {
  const def = findTable(raw);
  if (!def) {
    throw new DomainError("TABLE_NOT_FOUND", `沒有 ${String(raw)} 這一桌`);
  }
  return def.id;
}

/**
 * 有哪些桌（桌邊結帳計劃 [S12]）：給手機上的「模擬掃碼」選桌畫面用。
 *
 * ★只給桌號、區、座位數★，不給「那桌有沒有人、點了什麼、多少錢」——
 * POS 的桌位圖有那些，客人端刻意不沿用。清單直接讀後端那一份，
 * 手機上不另外抄一份桌號（兩份一定漂移）。
 */

/**
 * 一個可選的加料／調味（計劃 [S1]）。
 * `price` 是**價差**，整數元，可以是 0（例如「去冰」不加價）。
 */
export interface MenuOption {
  readonly id: string;
  readonly name: string;
  readonly price: number;
}

/**
 * 選項組（計劃 [S1]）。
 *
 * ★用「最少選幾個／最多選幾個」表達，而不是「必選」「可複選」兩個布林★：
 * 甜度是「剛好一個」（1,1）、加料是「零到多個」（0,3）、麵量是「剛好一個」（1,1）——
 * 一組數字就表達得完。兩個布林反而會生出「必選但不可選」這種互相矛盾的組合。
 */
export interface OptionGroup {
  readonly id: string;
  readonly name: string;
  readonly min: number;
  readonly max: number;
  readonly options: readonly MenuOption[];
}

/**
 * 套餐的一個選配（套餐計劃 [S1]／[S2]）。
 *
 * `itemId` 指向菜單上真的存在的品項——★不能憑空造一個選項★，要賣就先進菜單，
 * 否則廚房收到一個查不到作法的東西。`extra` 是加價，可以是 0。
 */
export interface ComboChoice {
  readonly itemId: string;
  readonly extra: number;
}

/**
 * 套餐選配組（套餐計劃 [S1]）：**剛好選一個**。
 *
 * ★這裡不用「最少／最多」那組數字★（加料組才用）：套餐的意思就是

/**
 * 金額全部是整數新台幣元。★這個檔是四捨五入唯一被允許發生的地方★（計劃 [S6]）。
 *
 * 為什麼要集中：服務費散在各處各算各的，是這類系統對不上帳的頭號原因；
 * 集中之後，改壞它只會有一支測試紅，而不是每張單少收一點卻沒人發現。
 */

/** 服務費率 10%，寫成「乘 10 再除 100」的整數形式。 */
const SERVICE_NUMERATOR = 10;
const SERVICE_DENOMINATOR = 100;

/**
 * 服務費 = 小計 × 10%，四捨五入到元。
 *
 * 寫法：先用取餘數把被除數削成 100 的整數倍再除。除以 100 的精確倍數在 IEEE754 下是精確的。
 *
 * ★誠實說明（2026-09-09 自己做翻紅驗證時發現）★：我原本在這裡寫「`Math.trunc(x / 100)`
 * 不精確」——**那是沒驗過就下的斷言，而且是錯的**。實際把這一行換成 `Math.trunc(scaled / 100)`
 * 再跑同一支合約測試，★全部通過★。推導也支持：被除數是安全整數時，商的誤差永遠小於
 * 讓截斷結果差一的距離。所以這個寫法不是在修一個已發生的錯，只是把「這裡不碰浮點」
 * 這條約束寫成程式碼看得出來的樣子。**「不碰浮點」這半條合約目前沒有任何測試釘得住。**
 *
 * 先驗：小計 15 → (150+50)=200，200-0=200，200/100 = 2（1.5 進位）
 *       小計 14 → (140+50)=190，190-90=100，100/100 = 1（1.4 捨去）
 *       小計 25 → (250+50)=300，300/100 = 3（2.5 進位）
 */
export function serviceCharge(subtotal: number): number {
  if (!Number.isSafeInteger(subtotal) || subtotal < 0) {
    throw new RangeError(`小計必須是 0 以上的安全整數，收到 ${subtotal}`);
  }
  const scaled = subtotal * SERVICE_NUMERATOR + SERVICE_DENOMINATOR / 2;
  if (!Number.isSafeInteger(scaled)) {
    throw new RangeError(`小計大到會讓服務費算不準（${subtotal}）`);
  }
  return (scaled - (scaled % SERVICE_DENOMINATOR)) / SERVICE_DENOMINATOR;
}

/**
 * 百分比折扣金額 = 小計 × 百分比，四捨五入到元（計劃 [S2]）。
 *

