/** 後端位址。開發時走 vite 的代理,部署時是同一個網域。 */
export const API_BASE = import.meta.env.VITE_API_BASE || ''

async function call(method, path, body) {
  let res
  try {
    res = await fetch(API_BASE + path, {
      method,
      headers: body === undefined ? {} : { 'content-type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    })
  } catch (e) {
    // ★連不上跟「後端說不行」是兩件事★:一個要客人檢查網路,一個要客人改點別的
    throw { kind: 'network', message: '連不上店家的系統，請檢查網路或叫服務人員。' }
  }
  const json = await res.json().catch(() => null)
  if (!res.ok) {
    // ★用後端給的那句話★（計劃 [S2]）:自己另編一句的話,同一個問題會有兩種說法
    throw { kind: 'api', code: json?.error?.code, message: json?.error?.message || '操作沒有成功。' }
  }
  return json
}

