 * 跟後端的併列規則同一個意思，送過去之後才會一列對一列。
 */
export function lineKey(itemId, options, combo) {
  const opt = sorted(options).join(',')
  const picks = (combo || [])
    .map((p) => `${p.groupId}:${p.itemId}(${sorted(p.options).join(',')})`)
    .sort()
    .join('|')
  return `${itemId}#${opt}#${picks}`
}

/** 放一份進購物車；同一列就加一，不同就新開一列。 */
