export function tableFromLocation(search, pathname) {
  const q = new URLSearchParams(search || '')
  const fromQuery = q.get('t') || q.get('table')
  if (fromQuery) return fromQuery.trim() || null
  // 也接受 /A1 這種路徑形式（QR 碼比較短）
  const seg = (pathname || '').split('/').filter(Boolean)
  const last = seg[seg.length - 1]
  if (last && /^[A-Za-z]\d+$/.test(last)) return last
  return null
}

