/// 一個可選的加料／調味。`price` 是**價差**（可以是 0）。
struct MenuOption: Codable, Identifiable, Equatable {
    let id: String
    let name: String
    let price: Int
}

/// 選項組。`min`／`max` 是「最少選幾個／最多選幾個」。
///
/// ★不用「必選」「可複選」兩個布林★（照後端合約）：一組數字就表達得完，
/// 兩個布林反而生得出「必選但不可選」這種矛盾組合。
struct OptionGroup: Codable, Identifiable, Equatable {
    let id: String
    let name: String
    let min: Int
    let max: Int
    let options: [MenuOption]

    /// 剛好要選一個（甜度、冰塊那種）。
    var isSingleRequired: Bool { min == 1 && max == 1 }
    /// 這一組非選不可。
    var isRequired: Bool { min > 0 }
}

/// 套餐的一個選配。`itemId` 指向菜單上真的存在的品項；`extra` 是加價（可以是 0）。
