/// 可注入的傳輸層。★測試靠它驗「組出來的請求對不對」★（計劃 [S6]／[S14]）——
/// 直接用 `URLSession.shared` 的話那條條款就永遠驗不到。
protocol PosTransport {
    func send(_ request: URLRequest) async throws -> (Data, HTTPURLResponse)
}

struct UrlSessionTransport: PosTransport {
    func send(_ request: URLRequest) async throws -> (Data, HTTPURLResponse) {
        let (data, response) = try await URLSession.shared.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw PosError.transport("回應不是 HTTP")
        }
        return (data, http)
    }
}

