/// 後端推過來的一則「有東西變了」。
///
/// ★這個型別刻意只有四個欄位★（計劃 [S1]）：什麼變了、哪張單、哪一桌、什麼時候。
/// **沒有品項、沒有金額——不是忘了放，是刻意不放。**
///
/// 它是門鈴，不是包裹：響了只代表有人來，還是要自己去開門看。
/// 推出去的那一刻那張單可能又被別人改了，把整張單塞進來的話，
/// 收到的人會拿著過期的快照當最新的用。兩台 POS 加客人的手機同時改同一張單是常態。
///
/// 做不到「拿事件當資料來源」這件事本身就是保證，比寫一條「不要這樣做」的規則強。
struct PosOrderEvent: Decodable, Equatable {
    /// 什麼變了。★不認得的種類不得讓整則解不出來★——照 `OrderStatus` 的先例留一個 unknown。
    enum Kind: Equatable {
        case guestSent, orderChanged, orderGone
        case unknown(String)

        init(raw: String) {
            switch raw {
            case "guest-sent": self = .guestSent
            case "order-changed": self = .orderChanged
            case "order-gone": self = .orderGone
            default: self = .unknown(raw)
            }
        }

        /// 要不要跳提示給店員看。★只有客人在手機上送了一輪單才跳★（桌邊送單收單計劃 [S1]）：
        /// 店員自己的動作後端也會推，全跳的話這台 POS 會被自己按的每一下洗版。
        /// 舊的「客人加菜」「客人結帳」後端都不送了，送來也當沒見過的種類、不跳。
        var raisesBanner: Bool { self == .guestSent }
    }

    let kind: Kind
    let orderId: String
    let table: String?
    let at: String

    private enum CodingKeys: String, CodingKey { case kind, orderId, table, at }

