/// 把決策層接到畫面上。★這裡只做流程編排，不做判斷也不算錢★。
@MainActor
final class PosViewModel: ObservableObject {
    @Published private(set) var state = PosScreenState()
    @Published private(set) var busy = false

    private let client: PosApiClient
    private let events: PosEventStream?

    init(client: PosApiClient, events: PosEventStream? = nil) {
        self.client = client
        self.events = events
    }

    /// 給截圖產生器用:直接餵一個狀態進來。★決策層與畫面完全不變★;
    /// 傳入的 client 決定 `.task` 那次載入菜單會拿到什麼(截圖時餵一個假的傳輸層)。
    init(preloaded: PosScreenState, client: PosApiClient) {
        self.client = client
        self.events = nil
        self.state = preloaded
    }

    // MARK: - 即時收單（即時收單計劃）

    /// 接上後端那條長連線。★App 一啟動就接★，之後由它自己維持。
    func startListening() {
        events?.start(
            onEvent: { [weak self] ev in
                guard let self else { return }
                Task { await self.receive(ev) }
